// Pure builder of the notification the service worker shows on `push` (src/sw.ts).
// Bundled into sw.js: imports only ./notificationClick (no React, no DOM).
// Golden rule (iOS): EVERY push shows a notification, so anything unreadable becomes the generic one.
import { PUSH_FALLBACK_URL, safeNotificationUrl, type PushNotificationData } from "./notificationClick";

export const GENERIC_PUSH_TITLE = "Novidade no HNBCRM";
export const GENERIC_PUSH_BODY = "Toque para abrir.";
export const GENERIC_PUSH_TAG = "hnb-generic";
/** Icons generated by A1 (public/). The badge is the white, transparent logo (Android uses its alpha). */
export const PUSH_ICON = "/pwa-192x192.png";
export const PUSH_BADGE_ICON = "/white_icon_logo_transparent-bg-528x488.png";

const TITLE_MAX = 120;
const BODY_MAX = 280;
const TAG_MAX = 64;
const ACTION_TITLES: Record<string, string> = { assumir: "Assumir", abrir: "Abrir" };

/** NotificationOptions plus the fields lib.webworker does not type (actions, renotify). */
export type BuiltNotificationOptions = NotificationOptions & {
  renotify?: boolean;
  actions?: { action: string; title: string }[];
  data: PushNotificationData;
};

export type BuiltNotification = {
  title: string;
  options: BuiltNotificationOptions;
  /** App icon counter to apply (`setAppBadge`), when the payload carried one. */
  appBadge?: number;
  generic: boolean;
};

const str = (v: unknown, max: number): string | undefined => {
  if (typeof v !== "string") return undefined;
  const t = v.trim();
  if (!t) return undefined;
  const cps = Array.from(t);
  return cps.length > max ? cps.slice(0, max - 1).join("") + "…" : t;
};

const obj = (v: unknown): Record<string, unknown> | null =>
  v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : null;

const badgeOf = (v: unknown): number | undefined =>
  typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.min(Math.floor(v), 999) : undefined;

export function genericNotification(): BuiltNotification {
  return {
    title: GENERIC_PUSH_TITLE,
    generic: true,
    options: {
      body: GENERIC_PUSH_BODY,
      tag: GENERIC_PUSH_TAG,
      lang: "pt-BR",
      dir: "auto",
      icon: PUSH_ICON,
      badge: PUSH_BADGE_ICON,
      silent: false,
      data: { url: PUSH_FALLBACK_URL },
    },
  };
}

/**
 * Builds title + options from the E1 payload (`{web_push, notification, hnb}`, convex/lib/webPush.ts).
 * Uses `hnb.url` (relative) for the click, never `notification.navigate` (absolute, Declarative only).
 * `data` carries only ids, type and relative URLs (no text beyond what the notification shows).
 */
export function buildNotification(payload: unknown, opts: { supportsActions: boolean }): BuiltNotification {
  const root = obj(payload);
  const n = obj(root?.notification);
  const hnb = obj(root?.hnb);
  const title = str(n?.title, TITLE_MAX);
  if (!root || !n || !title) return genericNotification();

  const url = safeNotificationUrl(hnb?.url) ?? PUSH_FALLBACK_URL;
  const tag = str(hnb?.tag, TAG_MAX) ?? str(n.tag, TAG_MAX);
  const body = str(n.body, BODY_MAX);
  const renotify = (hnb?.renotify ?? n.renotify) === true && !!tag; // renotify without tag throws
  const appBadge = badgeOf(hnb?.badge ?? n.app_badge);

  const data: PushNotificationData = { url };
  if (typeof hnb?.notificationId === "string") data.notificationId = hnb.notificationId;
  if (typeof hnb?.organizationId === "string") data.organizationId = hnb.organizationId;
  if (typeof hnb?.type === "string") data.type = hnb.type;

  const actions: { action: string; title: string }[] = [];
  if (opts.supportsActions && Array.isArray(hnb?.actions)) {
    for (const raw of hnb.actions as unknown[]) {
      const a = obj(raw);
      const name = typeof a?.action === "string" ? a.action : "";
      if (!(name in ACTION_TITLES) || actions.some((x) => x.action === name)) continue;
      if (name === "assumir") {
        const au = safeNotificationUrl(a?.url);
        if (!au) continue;
        data.actionUrls = { ...(data.actionUrls ?? {}), assumir: au };
      }
      actions.push({ action: name, title: ACTION_TITLES[name] });
    }
  }

  const options: BuiltNotificationOptions = {
    lang: "pt-BR",
    dir: "auto",
    icon: PUSH_ICON,
    badge: PUSH_BADGE_ICON,
    silent: false,
    data,
  };
  if (body) options.body = body;
  if (tag) options.tag = tag;
  if (renotify) options.renotify = true;
  if (actions.length > 0) options.actions = actions;
  return { title, options, generic: false, ...(appBadge !== undefined ? { appBadge } : {}) };
}

/** Parses `PushEvent.data` without throwing (`json()` throws on non-JSON). */
export function readPushData(data: { json(): unknown } | null | undefined): unknown {
  if (!data) return null;
  try {
    return data.json();
  } catch {
    return null;
  }
}
